package app.tonal.android;

import android.os.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Bounded metadata repair, independent of playback. Never guesses an ambiguous artist. */
final class MusicMetadata implements AutoCloseable {
    private final MusicStore store; private final SpotifyClient api;
    private final Handler main=new Handler(Looper.getMainLooper());
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final ArrayDeque<String> queue=new ArrayDeque<>();
    private final Set<String> pending=new HashSet<>(); private boolean busy;private volatile boolean closed; private long lastRequest;
    MusicMetadata(MusicStore store,SpotifyClient api){this.store=store;this.api=api;}
    boolean uses(SpotifyClient client){return api==client;}
    void recent(){JSONArray events=MusicStore.array(store.data,"events");int added=0;Set<String> seen=new HashSet<>();for(int i=events.length()-1;i>=0&&added<24;i--){String k=events.optJSONObject(i).optString("key");JSONObject t=MusicStore.object(store.data,"tracks").optJSONObject(k);if(t!=null&&seen.add(k)){enrich(t);added++;}}}
    void enrich(JSONObject t){if(closed)return;String key=MusicStore.key(t);JSONObject cached=MusicStore.object(MusicStore.object(store.data,"metadataChecks"),key);if(System.currentTimeMillis()-cached.optLong("at")<cached.optLong("ttl",3600000))return;if(queue.size()>=32||!pending.add(key))return;queue.add(key);next();}
    private void next(){if(closed||busy||queue.isEmpty())return;busy=true;String key=queue.remove();JSONObject t=MusicStore.object(store.data,"tracks").optJSONObject(key);if(t==null){done(key,false);return;}
        if(api!=null&&api.loggedIn()&&t.optString("provider").equals("Spotify")&&(t.optString("album").isEmpty()||t.optString("image").isEmpty()||t.optString("artistId").isEmpty())){
            String id=t.optString("uri").replace("spotify:track:","");if(id.matches("[A-Za-z0-9]{22}")){api.get("tracks/"+id,j->{store.mergeMetadata(key,MusicStore.spotifyTrack(j));artist(key);},e->artist(key));return;}
        }artist(key);
    }
    private void artist(String key){if(closed)return;JSONObject t=MusicStore.object(MusicStore.object(store.data,"tracks"),key);if(!t.optString("genre").isEmpty()){done(key,true);return;}
        String artistId=t.optString("artistId");JSONObject cached=MusicStore.object(MusicStore.object(store.data,"artistMetadata"),artistId);
        if(!artistId.isEmpty()&&System.currentTimeMillis()-cached.optLong("at")<30L*86400000&&!cached.optString("genre").isEmpty()){applyArtist(artistId,cached);done(key,true);return;}
        if(api!=null&&api.loggedIn()&&artistId.matches("[A-Za-z0-9]{22}")){api.get("artists/"+artistId,j->{String genre=join(MusicStore.array(j,"genres"));if(!genre.isEmpty()){JSONObject patch=new JSONObject();MusicStore.put(patch,"genre",genre);MusicStore.put(patch,"genreSource","Spotify • artista");MusicStore.put(patch,"at",System.currentTimeMillis());JSONObject all=MusicStore.object(store.data,"artistMetadata");MusicStore.put(all,artistId,patch);MusicStore.put(store.data,"artistMetadata",all);applyArtist(artistId,patch);done(key,true);}else fallback(key);},e->fallback(key));}else fallback(key);
    }
    private void applyArtist(String id,JSONObject patch){if(closed)return;JSONObject tracks=MusicStore.object(store.data,"tracks");ArrayList<String> keys=new ArrayList<>();tracks.keys().forEachRemaining(keys::add);for(String k:keys)if(id.equals(MusicStore.object(tracks,k).optString("artistId")))store.mergeMetadata(k,patch);}
    private static String join(JSONArray a){StringJoiner out=new StringJoiner(", ");for(int i=0;i<Math.min(4,a.length());i++)out.add(a.optString(i));return out.toString();}
    private JSONObject mb(String path)throws Exception{long wait=1200-(SystemClock.elapsedRealtime()-lastRequest);if(wait>0)Thread.sleep(wait);lastRequest=SystemClock.elapsedRealtime();for(int attempt=0;;attempt++){try{return WebRequest.json("https://musicbrainz.org/ws/2/"+path);}catch(WebRequest.Failure e){if(attempt>=2||!(e.code==429||e.code>=500))throw e;Thread.sleep(1500L*(attempt+1));lastRequest=SystemClock.elapsedRealtime();}}}
    static JSONObject uniqueArtist(JSONObject response,String name){JSONObject found=null;for(Object v:MusicStore.values(MusicStore.array(response,"artists"))){JSONObject a=(JSONObject)v;if(!IndieCatalog.normalize(name).equals(IndieCatalog.normalize(a.optString("name")))||a.optInt("score")<98)continue;if(found!=null)return null;found=a;}return found;}
    static String genres(JSONObject artist){ArrayList<JSONObject> tags=new ArrayList<>();for(String field:new String[]{"genres","tags"})for(Object v:MusicStore.values(MusicStore.array(artist,field)))if(v instanceof JSONObject&&!((JSONObject)v).optString("name").isEmpty())tags.add((JSONObject)v);tags.sort(Comparator.comparingInt((JSONObject x)->x.optInt("count")).reversed());LinkedHashSet<String> names=new LinkedHashSet<>();for(JSONObject tag:tags)if(names.size()<4&&tag.optInt("count")>0)names.add(tag.optString("name"));return String.join(", ",names);}
    private void fallback(String key){if(closed)return;JSONObject t=MusicStore.object(MusicStore.object(store.data,"tracks"),key);String name=t.optString("artist"),cacheKey=name+"|"+t.optString("album");JSONObject cache=MusicStore.object(MusicStore.object(store.data,"publicArtistMetadata"),cacheKey);if(System.currentTimeMillis()-cache.optLong("at")<30L*86400000&&!cache.optString("genre").isEmpty()){store.mergeMetadata(key,cache);done(key,true);return;}if(name.isEmpty()){done(key,false);return;}worker.execute(()->{String genre="";try{JSONObject search=mb("artist/?fmt=json&limit=8&query="+SpotifyClient.encode("artist:\""+name.replace("\"","")+"\""));JSONObject artist=uniqueArtist(search,name);if(artist==null&&!t.optString("album").isEmpty()){String album=t.optString("album").replaceAll("\\s*\\(.*?\\)|\\s*\\[.*?\\]","").trim();JSONObject releases=mb("release-group/?fmt=json&limit=10&query="+SpotifyClient.encode("artist:\""+name.replace("\"","")+"\" AND releasegroup:\""+album.replace("\"","")+"\""));String confirmed="";boolean conflict=false;for(Object v:MusicStore.values(MusicStore.array(releases,"release-groups"))){JSONObject r=(JSONObject)v;if(!IndieCatalog.normalize(album).equals(IndieCatalog.normalize(r.optString("title"))))continue;for(Object credit:MusicStore.values(MusicStore.array(r,"artist-credit"))){JSONObject a=MusicStore.object((JSONObject)credit,"artist");if(!IndieCatalog.normalize(name).equals(IndieCatalog.normalize(a.optString("name"))))continue;String id=a.optString("id");if(!confirmed.isEmpty()&&!confirmed.equals(id))conflict=true;confirmed=id;}}if(!conflict&&!confirmed.isEmpty()){artist=new JSONObject();MusicStore.put(artist,"id",confirmed);}}if(artist!=null)genre=genres(mb("artist/"+artist.optString("id")+"?fmt=json&inc=genres+tags"));}catch(Exception ignored){}String result=genre;main.post(()->{if(!result.isEmpty()){JSONObject patch=new JSONObject();MusicStore.put(patch,"genre",result);MusicStore.put(patch,"genreSource","MusicBrainz • artista confirmado");MusicStore.put(patch,"at",System.currentTimeMillis());JSONObject cacheAll=MusicStore.object(store.data,"publicArtistMetadata");MusicStore.put(cacheAll,cacheKey,patch);if(cacheAll.length()>1000)cacheAll.remove(cacheAll.keys().next());MusicStore.put(store.data,"publicArtistMetadata",cacheAll);store.mergeMetadata(key,patch);}done(key,!result.isEmpty());});});}
    private void done(String key,boolean success){if(closed)return;JSONObject checks=MusicStore.object(store.data,"metadataChecks"),entry=new JSONObject();MusicStore.put(entry,"at",System.currentTimeMillis());MusicStore.put(entry,"ttl",success?30L*86400000:3600000);MusicStore.put(checks,key,entry);if(checks.length()>3000)checks.remove(checks.keys().next());MusicStore.put(store.data,"metadataChecks",checks);store.save();pending.remove(key);busy=false;main.postDelayed(this::next,250);}
    public void close(){closed=true;worker.shutdownNow();main.removeCallbacksAndMessages(null);queue.clear();pending.clear();busy=false;}
}
